                                                "id": "availability-heuristic",
                                                "title": "Availability Heuristic",
                                                "icon": "far fa-file-alt",
                                                "desc": "",
                                                "tags": [
                                                    "Psychology",
                                                    "Media",
                                                    "RiskAssessment"
                                                ],
